use lb_binary_codec::canonical::codec_fixtures;
use lb_groth16::CompressedGroth16VerificationKey;

use crate::mantle::programs::ProgramVerificationKey;

pub fn placeholder_key() -> ProgramVerificationKey {
    ProgramVerificationKey::new(CompressedGroth16VerificationKey {
        alpha_1: [0x3e; 32].into(),
        beta_2: [0x3f; 64].into(),
        gamma_2: [0x40; 64].into(),
        delta_2: [0x41; 64].into(),
        ic: vec![
            [0x42; 32].into(),
            [0x43; 32].into(),
            [0x44; 32].into(),
            [0x45; 32].into(),
        ],
    })
    .expect("the placeholder key holds 4 ic points")
}

codec_fixtures!(
    ProgramVerificationKey,
    placeholder_key() => ""
);
